import os
import base64
from typing import Optional, Dict, Any

import requests


VAULT_ADDR = os.environ["VAULT_ADDR"].rstrip("/")
VAULT_TOKEN = os.environ["VAULT_TOKEN"]


class VaultTransitSigner:
    def __init__(self, vault_addr: str = VAULT_ADDR, vault_token: str = VAULT_TOKEN) -> None:
        self.vault_addr = vault_addr.rstrip("/")
        self.session = requests.Session()
        self.session.headers.update(
            {
                "X-Vault-Token": vault_token,
                "Content-Type": "application/json",
            }
        )

    @staticmethod
    def _b64(data: bytes) -> str:
        return base64.b64encode(data).decode("ascii")

    def _post(self, path: str, payload: Dict[str, Any]) -> Dict[str, Any]:
        url = f"{self.vault_addr}/v1/{path.lstrip('/')}"
        resp = self.session.post(url, json=payload, timeout=30)
        resp.raise_for_status()
        body = resp.json()
        if "errors" in body and body["errors"]:
            raise RuntimeError(f"Vault error: {body['errors']}")
        return body.get("data", {})

    def create_signing_key(
        self,
        key_name: str,
        key_type: str = "ecdsa-p256",
        exportable: bool = False,
        allow_plaintext_backup: bool = False,
    ) -> Dict[str, Any]:
        return self._post(
            f"transit/keys/{key_name}",
            {
                "type": key_type,
                "exportable": exportable,
                "allow_plaintext_backup": allow_plaintext_backup,
            },
        )

    def sign(
        self,
        key_name: str,
        message: bytes,
        hash_algorithm: str = "sha2-256",
        signature_algorithm: Optional[str] = None,
        prehashed: bool = False,
        marshaling_algorithm: Optional[str] = None,
        key_version: Optional[int] = None,
        context: Optional[bytes] = None,
    ) -> str:
        payload: Dict[str, Any] = {
            "input": self._b64(message),
            "hash_algorithm": hash_algorithm,
            "prehashed": prehashed,
        }
        if signature_algorithm is not None:
            payload["signature_algorithm"] = signature_algorithm
        if marshaling_algorithm is not None:
            payload["marshaling_algorithm"] = marshaling_algorithm
        if key_version is not None:
            payload["key_version"] = key_version
        if context is not None:
            payload["context"] = self._b64(context)

        data = self._post(f"transit/sign/{key_name}", payload)
        signature = data.get("signature")
        if not signature:
            raise RuntimeError("Vault did not return a signature")
        return signature

    def verify(
        self,
        key_name: str,
        message: bytes,
        signature: str,
        hash_algorithm: str = "sha2-256",
        signature_algorithm: Optional[str] = None,
        prehashed: bool = False,
        marshaling_algorithm: Optional[str] = None,
        context: Optional[bytes] = None,
    ) -> bool:
        payload: Dict[str, Any] = {
            "input": self._b64(message),
            "signature": signature,
            "hash_algorithm": hash_algorithm,
            "prehashed": prehashed,
        }
        if signature_algorithm is not None:
            payload["signature_algorithm"] = signature_algorithm
        if marshaling_algorithm is not None:
            payload["marshaling_algorithm"] = marshaling_algorithm
        if context is not None:
            payload["context"] = self._b64(context)

        data = self._post(f"transit/verify/{key_name}", payload)
        return bool(data.get("valid", False))
